import numpy as np


def best_round(losses):
    values = np.asarray(losses, dtype=float)
    if values.ndim != 1 or len(values) == 0 or not np.isfinite(values).all():
        raise ValueError("Finite loss curve")
    return int(np.argmin(values))  # earliest exact tie


assert best_round([0.8, 0.6, 0.61, 0.6, 0.7]) == 1
print(
    best_round([0.8, 0.6, 0.61, 0.6, 0.7])
)  # illustrative curve, not real measurements

